<body>

<header>
  <div>
    <h1>Sales Analytics Dashboard</h1>
    <div class="sub">Deterministic sample data &middot; live filters &middot; inline SVG visualizations</div>
  </div>

  <div class="controls">
    <div class="ctrl-group">
      <label for="fRegion">Region</label>
      <select id="fRegion"></select>
    </div>
    <div class="ctrl-group">
      <label for="fCategory">Category</label>
      <select id="fCategory"></select>
    </div>
    <div class="ctrl-group">
      <label for="fPeriod">Period range</label>
      <div class="range-row">
        <input type="range" id="fPeriod" min="0" max="11" value="0">
        <span class="range-val" id="periodVal">Jan 2025 &ndash; Jan 2025</span>
      </div>
    </div>
    <button class="btn" id="refreshBtn" type="button">Refresh data</button>
  </div>
</header>

<section class="kpis" id="kpis"></section>

<section class="grid">
  <div class="chart wide">
    <h3>Revenue Trend Over Time</h3>
    <div class="c-sub">Monthly revenue by region (hover the line marks for details)</div>
    <div class="vis" id="trend"></div>
  </div>
  <div class="chart">
    <h3>Revenue by Category</h3>
    <div class="c-sub">Total revenue grouped by product category (hover bars)</div>
    <div class="vis" id="bars"></div>
  </div>
  <div class="chart">
    <h3>Regional Revenue Share</h3>
    <div class="c-sub">Share of filtered revenue by region (hover segments)</div>
    <div class="vis" id="donut"></div>
  </div>
  <div class="chart wide">
    <h3>Spend vs Revenue</h3>
    <div class="c-sub">Each point is a region &times; category &times; month sample (hover dots)</div>
    <div class="vis" id="scatter"></div>
  </div>
</section>

<div id="tooltip"></div>

<script>
(function () {
  "use strict";

  var REGIONS = ["North", "South", "East", "West"];
  var CATS = ["Electronics", "Clothing", "Home", "Grocery"];
  var MONTHS = [
    "Jan 2025", "Feb 2025", "Mar 2025", "Apr 2025", "May 2025", "Jun 2025",
    "Jul 2025", "Aug 2025", "Sep 2025", "Oct 2025", "Nov 2025", "Dec 2025"
  ];

  var style = getComputedStyle(document.documentElement);
  var CAT_COLOR = {};
  var CATS.forEach(function (c, i) {
    CAT_COLOR[c] = [ "--accent", "--teal", "--violet", "--amber" ][i % 4];
  });
  function css(k) { return style.getPropertyValue(k).trim(); }

  var seedVal = 20250101;
  function mulberry32(a) {
    return function () {
      a |= 0; a = (a + 0x6D2B79F5) | 0;
      var t = Math.imul(a ^ (a >>> 15), 1 | a);
      t = (t + Math.imul(t ^ (t >>> 7), 61 | t)) ^ t;
      return ((t ^ (t >>> 14)) >>> 0) / 4294967296;
    };
  }

  var data = [];

  function generate(seed) {
    var rand = mulberry32(seed);
    var out = [];
    var n = 0;
    REGIONS.forEach(function (region) {
      CATS.forEach(function (cat) {
        var base = 12000 + rand() * 22000;
        var growth = 0.5 + rand() * 0.6;
        var seasonal = 0.35 + rand() * 0.4;
        var orderSpend = 40 + rand() * 120;
        var marginBias = 0.18 + rand() * 0.25;
        for (var m = 0; m < 12; m++) {
          var wave = 1 + (seasonal * Math.sin((m / 12) * Math.PI * 2));
          var trendF = 1 + (growth * (m / 12));
          var jitter = 0.94 + rand() * 0.12;
          var revenue = Math.round(base * wave * trendF * jitter);
          var orderPrice = orderSpend * (0.9 + rand() * 0.2);
          var orders = Math.max(8, Math.round(revenue / orderPrice));
          var spend = Math.round(revenue * (0.52 + 0.3 * rand() - marginBias * 0.6));
          if (spend < revenue * 0.1) spend = Math.round(revenue * 0.35);
          out.push({
            idx: n++, region: region, cat: cat, m: m,
            revenue: revenue, orders: orders, spend: spend,
            profit: revenue - spend,
            margin: ((revenue - spend) / revenue) * 100
          });
        }
      });
    });
    return out;
  }

  var state = { region: "All", cat: "All", periodEnd: 11, seed: seedVal };

  function initSeed() { data = generate(state.seed); }

  function filtered() {
    var reg = state.region, cat = state.cat, end = state.periodEnd;
    return data.filter(function (d) {
      if (reg !== "All" && d.region !== reg) return false;
      if (cat !== "All" && d.cat !== cat) return false;
      return d.m <= end;
    });
  }

  function fmt(n) {
    if (n >= 1e6) return (n / 1e6).toFixed(1) + "M";
    if (n >= 1e3) return (n / 1e3).toFixed(0) + "k";
    return String(Math.round(n));
  }
  function money(n) { return "$" + fmt(n); }

  function renderKPIs(list) {
    var revenue = 0, orders = 0, spend = 0;
    list.forEach(function (d) { revenue += d.revenue; orders += d.orders; spend += d.spend; });
    var aov = orders ? revenue / orders : 0;
    var marginPct = revenue ? ((revenue - spend) / revenue) * 100 : 0;

    var kpiDefinitions = [
      { label: "Revenue", value: money(revenue), delta: "+12.4% vs prev", up: true, icon: "M3 17l6-6 4 4 8-8m0 0h-5m5 0v5" },
      { label: "Orders", value: String(orders), delta: "+8.1% vs prev", up: true, icon: "M5 8h14M5 12h14M5 16h9" },
      { label: "Avg Order Value", value: money(aov), delta: "+3.9% vs prev", up: true, icon: "M12 8c-2.2 0-4 1.3-4 3s1.8 3 4 3 4 1.3 4 3-1.8 3-4 3m0-12V5m0 14v-1" },
      { label: "Profit Margin", value: marginPct.toFixed(1) + "%", delta: revenue - spend, up: true, icon: "M12 2v20M17 7c0-2-2-3.5-5-3.5S7 5 7 7s2 3 5 3.5 5 1.5 5 3.5-2 3.5-5 3.5S7 17 7 15" }
    ];

    var pct = marginPct.toFixed(1) + "%";
    kpiDefinitions[3].value = pct;
    kpiDefinitions[3].delta = "$" + fmt(revenue - spend) + " profit";

    var el = document.getElementById("kpis");
    el.innerHTML = kpiDefinitions.map(function (k) {
      return '<div class="kpi">' +
        '<svg width="20" height="20" viewBox="0 0 24 24" fill="none" stroke="' + css("--accent") + '" stroke-width="2" stroke-linecap="round" stroke-linejoin="round"><path d="' + k.icon + '"/></svg>' +
        '<div class="k-label">' + k.label + '</div>' +
        '<div class="k-value">' + k.value + '</div>' +
        '<div class="k-delta"><span class="up">&uarr; ' + k.delta + '</span></div>' +
        '</div>';
    }).join("");
  }

  // ---------- Tooltip ----------
  var tip = document.getElementById("tooltip");
  function showTip(html, ev) {
    tip.innerHTML = html;
    tip.style.display = "block";
    moveTip(ev);
  }
  function moveTip(ev) {
    var pad = 16;
    var x = ev.clientX + pad, y = ev.clientY + pad;
    var r = tip.getBoundingClientRect();
    if (x + r.width > window.innerWidth - 8) x = ev.clientX - r.width - pad;
    if (y + r.height > window.innerHeight - 8) y = ev.clientY - r.height - pad;
    tip.style.left = x + "px";
    tip.style.top = y + "px";
  }
  function hideTip() { tip.style.display = "none"; }
  function bindTip(el, html) {
    el.addEventListener("mousemove", function (e) { moveTip(e); });
    el.addEventListener("mouseenter", function (e) { showTip(html, e); });
    el.addEventListener("mouseleave", hideTip);
  }

  function mkW(name, attrs) {
    var ns = "http://www.w3.org/2000/svg";
    var s = document.createElementNS(ns, name);
    if (attrs) Object.keys(attrs).forEach(function (k) { s.setAttribute(k, attrs[k]); });
    return s;
  }

  // ---------- Line / Area trend ----------
  function renderTrend(list) {
    var wrap = document.getElementById("trend");
    wrap.innerHTML = "";
    var W = 940, H = 260, L = 54, R = 18, T = 18, B = 34;
    var months = [];
    for (var m = 0; m <= state.periodEnd; m++) months.push(m);
    var minM = 0, maxM = state.periodEnd;

    var all = data.filter(function (d) { return d.region === state.region || state.region === "All"; })
      .filter(function (d) {
        if (state.cat !== "All" && d.cat !== state.cat) return false;
        return true;
      });
    var maxV = 0;
    months.forEach(function (m) {
      var tot = 0;
      all.forEach(function (d) { if (d.m === m) tot += d.revenue; });
      if (tot > maxV) maxV = tot;
      var inSide = list.filter(function (d) { return d.m === m; });
      var s = 0; inSide.forEach(function (d) { s += d.revenue; });
      if (s > maxV) maxV = s;
    });
    maxV = maxV * 1.15 || 1;

    var x = function (m) { return L + ((m - minM) / Math.max(1, maxM - minM)) * (W - L - R); };
    var y = function (v) { return T + (1 - v / maxV) * (H - T - B); };

    var svg = mkW("svg", { viewBox: "0 0 " + W + " " + H });
    var defs = mkW("defs");
    var grad = mkW("linearGradient", { id: "trendFill", x1: "0", y1: "0", x2: "0", y2: "1" });
    var stop1 = mkW("stop", { offset: "0%", "stop-color": css("--accent"), "stop-opacity": "0.35" });
    var stop2 = mkW("stop", { offset: "100%", "stop-color": css("--accent"), "stop-opacity": "0" });
    grad.appendChild(stop1); grad.appendChild(stop2); defs.appendChild(grad); svg.appendChild(defs);

    var glines = 5;
    for (var i = 0; i <= glines; i++) {
      var v = maxV * (i / glines);
      var gy = y(v);
      var gl = mkW("line", { x1: L, y1: gy, x2: W - R, y2: gy, stroke: css("--border"), "stroke-width": 1, "stroke-dasharray": "3 4" });
      svg.appendChild(gl);
      var gt = mkW("text", { x: L - 8, y: gy + 3, "text-anchor": "end", "class": "axis" });
      gt.textContent = fmt(v);
      svg.appendChild(gt);
    }

    // aggregate by month across selected region(s)
    var byMonth = {};
    list.forEach(function (d) { byMonth[d.m] = (byMonth[d.m] || 0) + d.revenue; });
    var gx = L, gPath = "", aPath = "";
    months.forEach(function (m, i) {
      var tot = byMonth[m] || 0;
      var px = x(m), py = y(tot);
      if (i === 0) { gPath = "M" + px + " " + py; aPath = "M" + px + " " + (H - B); }
      else { gPath += " L" + px + " " + py; }
      aPath += " L" + px + " " + py;
    });
    aPath += " L" + x(maxM) + " " + (H - B) + " Z";
    var area = mkW("path", { d: aPath, fill: "url(#trendFill)" });
    svg.appendChild(area);
    var line = mkW("path", { d: gPath, fill: "none", stroke: css("--accent"), "stroke-width": 2.5, "stroke-linejoin": "round" });
    svg.appendChild(line);

    months.forEach(function (m) {
      var tot = byMonth[m] || 0;
      var px = x(m), py = y(tot);
      var c = mkW("circle", { cx: px, cy: py, r: 4.5, fill: css("--bg"), stroke: css("--accent"), "stroke-width": 2.5, "class": "mark" });
      bindTip(c, '<div class="tt-title">' + MONTHS[m] + '</div><div class="tt-row"><span class="tt-k">Revenue</span><span>' + money(tot) + '</span></div>');
      svg.appendChild(c);

      var tg = mkW("text", { x: px, y: H - 10, "text-anchor": "middle", "class": "axis" });
      tg.textContent = MONTHS[m].split(" ")[0];
      svg.appendChild(tg);
    });

    wrap.appendChild(svg);
  }

  // ---------- Bars by category ----------
  function renderBars(list) {
    var wrap = document.getElementById("bars");
    wrap.innerHTML = "";
    var W = 430, H = 250, L = 52, R = 14, T = 16, B = 30;
    var totals = {};
    var order = [];
    list.forEach(function (d) {
      if (!(d.cat in totals)) { totals[d.cat] = 0; order.push(d.cat); }
      totals[d.cat] += d.revenue;
    });
    order.sort(function (a, b) { return totals[b] - totals[a]; });
    var cats = CATS.filter(function (c) { return order.indexOf(c) >= 0; });
    if (cats.length === 0) cats = order;
    var maxV = Math.max.apply(null, cats.map(function (c) { return totals[c]; })) * 1.1 || 1;

    var n = cats.length;
    var slot = (W - L - R) / n;
    var bw = Math.min(48, slot * 0.55);

    var svg = mkW("svg", { viewBox: "0 0 " + W + " " + H });
    var y = function (v) { return T + (1 - v / maxV) * (H - T - B); };
    var ticks = 4;
    for (var i = 0; i <= ticks; i++) {
      var v = maxV * (i / ticks);
      var gy = y(v);
      var gl = mkW("line", { x1: L, y1: gy, x2: W - R, y2: gy, stroke: css("--border"), "stroke-width": 1, "stroke-dasharray": "3 4" });
      svg.appendChild(gl);
      var gt = mkW("text", { x: L - 8, y: gy + 3, "text-anchor": "end", "class": "axis" });
      gt.textContent = fmt(v);
      svg.appendChild(gt);
    }

    cats.forEach(function (c, i) {
      var cx = L + slot * i + slot / 2;
      var h = H - B - y(totals[c]);
      var x0 = cx - bw / 2, y0 = y(totals[c]);
      var color = css(CAT_COLOR[c]);
      var r = mkW("rect", { x: x0, y: y0, width: bw, height: h, rx: 6, fill: color, "class": "mark bar" });
      bindTip(r, '<div class="tt-title">' + c + '</div>' +
        '<div class="tt-row"><span class="tt-k">Revenue</span><span>' + money(totals[c]) + '</span></div>' +
