    var svg = mkW("svg", { viewBox: "0 0 " + S + " " + S, width: S, height: S });
    svg.style.display = "block";
    svg.style.margin = "0 auto";

    var flat = Math.PI * 2;
    var ang = -Math.PI / 2;

    // full ring decoration
    var ring = mkW("circle", { cx: cx, cy: cy, r: R, fill: "none", stroke: css("--border"), "stroke-width": 26 });
    svg.appendChild(ring);

    keys.forEach(function (k) {
      var frac = total ? totals[k] / total : 0;
      var a2 = ang + frac * flat;
      if (frac < 0.999) {
        var large = (a2 - ang) > Math.PI ? 1 : 0;
        var x1 = cx + R * Math.cos(ang), y1 = cy + R * Math.sin(ang);
        var x2 = cx + R * Math.cos(a2), y2 = cy + R * Math.sin(a2);
        var d = "M" + x1 + " " + y1 + " A " + R + " " + R + " 0 " + large + " 1 " + x2 + " " + y2;
        var seg = mkW("path", { d: d, fill: "none", stroke: css(["--accent","--teal","--violet","--amber"][REGIONS.indexOf(k)]), "stroke-width": 26, "class": "mark donut-seg" });
        bindTip(seg, '<div class="tt-title">' + k + '</div>' +
          '<div class="tt-row"><span class="tt-k">Revenue</span><span>' + money(totals[k]) + '</span></div>' +
          '<div class="tt-row"><span class="tt-k">Share</span><span>' + (frac * 100).toFixed(1) + '%</span></div>');
        svg.appendChild(seg);
      } else {
        var circ = mkW("circle", { cx: cx, cy: cy, r: R, fill: "none", stroke: css(["--accent","--teal","--violet","--amber"][REGIONS.indexOf(k)]), "stroke-width": 26, "class": "mark donut-seg" });
        bindTip(circ, '<div class="tt-title">' + k + '</div>' +
          '<div class="tt-row"><span class="tt-k">Revenue</span><span>' + money(totals[k]) + '</span></div>' +
          '<div class="tt-row"><span class="tt-k">Share</span><span>100%</span></div>');
