    list.forEach(function (d) {
      var px = x(d.spend), py = y(d.revenue);
      var dot = mkW("circle", { cx: px, cy: py, r: 5, fill: css(CAT_COLOR[d.cat]), "fill-opacity": 0.85, "class": "mark dot" });
