        '<div class="tt-row"><span class="tt-k">Period</span><span>' + MONTHS[d.m] + '</span></div>' +
        '<div class="tt-row"><span class="tt-k">Revenue</span><span>' + money(d.revenue) + '</span></div>' +
        '<div class="tt-row"><span class="tt-k">Spend</span><span>' + money(d.spend) + '</span></div>' +
        '<div class="tt-row"><span class="tt-k">Profit</span><span>' + money(d.revenue - d.spend) + '</span></div>');
      svg.appendChild(dot);
    });

    wrap.appendChild(svg);

    var legEl = document.createElement("div");
    legEl.className = "legend";
    CATS.forEach(function (c) {
      var sp = document.createElement("span");
      sp.innerHTML = '<span class="sw" style="background:' + css(CAT_COLOR[c]) + '"></span>' + c;
      legEl.appendChild(sp);
    });
    wrap.appendChild(legEl);
  }

  // ---------- Controls ----------
  function fillSelect(sel, values, current) {
